  if (R.mocap !== name) { if (R.mocap) { snapJoints(m, R); R.xfDur = 0.3; } R.mocap = name; R.mt = 0; R.loopN = 0; }
  // velocidade do passo acompanha a velocidade de andar (pé não "patina")
  let rate = 1;
  if (st === 'walk') rate = clamp(speed / 2.0, 0.6, 1.55);
  if (st === 'run') rate = clamp(speed / 4.6, 0.7, 1.45);
  R.mt += dt * rate;
  if (m.debugT != null) R.mt = m.debugT; // ferramenta de inspeção
