  if (Q.hdT <= 0) { Q.hdGoal = Math.random() < 0.35 ? 0 : (Math.random() - 0.5) * (deep ? 0.9 : 0.7); Q.hdT = 5 + Math.random() * 7; }
  Q.hd = damp(Q.hd, Q.hdGoal, 0.9, dt);
