      c.textAlign = 'left'; c.fillStyle = '#fff'; c.font = '700 28px Inter, sans-serif'; c.fillText(String(e.name).slice(0, 34), 156, y - 10);
      c.fillStyle = '#b9b2c6'; c.font = '500 21px Inter, sans-serif';
